#!/bin/sh
# Least-privilege application role for Atrium (runs once, on the first start of an empty data
# directory, from /docker-entrypoint-initdb.d).
#
#   POSTGRES_USER          owner/superuser role — schema changes only (`prisma migrate deploy`, MIGRATE_DATABASE_URL)
#   POSTGRES_APP_USER      application role (default atrium_app) — SELECT/INSERT/UPDATE/DELETE only (DATABASE_URL)
#   POSTGRES_APP_PASSWORD  its password (generated by `atrium setup production`)
#   POSTGRES_OWNER         optional: owner role when psql connects as another superuser (default POSTGRES_USER)
#
# Default privileges make every table/sequence the owner creates later (future migrations)
# usable by the app role automatically. For an existing database run the same SQL by hand —
# see docs/deployment/vps-podman.md ("Least-privilege database role").
set -eu

if [ -z "${POSTGRES_APP_PASSWORD:-}" ]; then
  echo "10-app-role.sh: POSTGRES_APP_PASSWORD is not set — skipping the application role (the app will use the owner role)" >&2
  exit 0
fi

psql -v ON_ERROR_STOP=1 --username "$POSTGRES_USER" --dbname "$POSTGRES_DB" \
  -v app_user="${POSTGRES_APP_USER:-atrium_app}" \
  -v app_password="$POSTGRES_APP_PASSWORD" \
  -v owner="${POSTGRES_OWNER:-$POSTGRES_USER}" \
  -v db="$POSTGRES_DB" <<'SQL'
SELECT format('CREATE ROLE %I LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS PASSWORD %L', :'app_user', :'app_password')
WHERE NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = :'app_user')
\gexec
REVOKE ALL ON DATABASE :"db" FROM PUBLIC;
GRANT CONNECT, TEMPORARY ON DATABASE :"db" TO :"app_user";
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO :"app_user";
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO :"app_user";
GRANT USAGE, SELECT, UPDATE ON ALL SEQUENCES IN SCHEMA public TO :"app_user";
ALTER DEFAULT PRIVILEGES FOR ROLE :"owner" IN SCHEMA public GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO :"app_user";
ALTER DEFAULT PRIVILEGES FOR ROLE :"owner" IN SCHEMA public GRANT USAGE, SELECT, UPDATE ON SEQUENCES TO :"app_user";
SQL
echo "10-app-role.sh: application role ${POSTGRES_APP_USER:-atrium_app} ready (DML only)"
